export default {"id": "07", "title": "偶尔后退，能否走得更远？", "outline": [10, 8], "catalog": {"A": [3, 2], "B": [2, 3], "C": [2, 2], "D": [3, 1], "E": [2, 2]}, "scenes": [{"key": "intro-why", "chapter": 1, "title": "编码都能解码，但该试哪一个？", "view": "intro-why07", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 18, "note": "序列对编码空间很大：14400个编码，搜索需要策略", "say": "前几课解决了\"从编码到布局\"。但一个五块问题就有14400个序列对编码，真实芯片的编码空间是天文数字。逐个试完不现实，需要搜索策略。本课用可复现的模拟退火：每步只看一个邻居，用明确的规则决定接受还是拒绝。", "start": 0, "delivery": "reading", "end": 18}, {"key": "intro-task", "chapter": 1, "title": "本课任务：读轨迹、审状态机、做比较", "view": "intro-goal07", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 18, "note": "当前/候选/最好分开；ΔE与温度；等预算多种子比较", "say": "本课的任务有三层：读懂一条真实轨迹里每一步的决策；审计\"拒绝后当前解被修改\"这类状态机错误；最后用相同种子集合、相同预算做等预算比较，区分邻域不足、接受行为和预算不足。", "start": 18, "delivery": "reading", "end": 36}, {"key": "intro-preview", "chapter": 1, "title": "一条真实轨迹的终点", "view": "board", "rows": [["A", 0, 1, 3, 2], ["B", 3, 0, 2, 3], ["C", 0, 3, 2, 2], ["D", 0, 0, 3, 1], ["E", 2, 3, 2, 2]], "seconds": 13, "note": "seed=7、T=12、120步：最好合法面积25", "say": "先看终点：固定种子7、温度12、120步，这次运行得到的最好合法布局面积25。注意现在是\"这一次运行\"的结果——它能不能稳定复现、换个种子还好不好，是本课要回答的问题。", "start": 36, "delivery": "reading", "end": 51.0}, {"key": "components", "chapter": 2, "title": "三份状态，各管各的", "view": "state-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "start", "note": "当前解、候选解、历史最好合法解：分开保存", "start": 51.0, "delivery": "voice", "end": 57.714}, {"key": "neighbor-swap", "chapter": 2, "title": "邻居：交换一个排列里的两个名字", "view": "neighbor-diagram", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "neighbor", "note": "改编码→重新解码→真算能量；不直接改坐标", "say": "邻居这样生成：在某一个排列里交换两个名字，比如pos里的B和E。然后重新解码得到完整布局，再真的计算能量——不是在旧布局上微调坐标。搜索变量始终是编码，布局只是解码的产物。", "start": 57.714, "delivery": "voice", "end": 64.836}, {"key": "delta", "chapter": 3, "title": "ΔE：候选比当前好多少", "view": "delta-view", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "delta", "note": "ΔE=候选能量−当前能量；≤0直接接受", "say": "能量E是盒面积加100倍的超宽超高。ΔE等于候选能量减当前能量：下降就是改进，直接接受；上升不一定拒绝——这正是退火的核心。", "start": 64.836, "delivery": "voice", "end": 71.094}, {"key": "probability", "chapter": 3, "title": "变差的候选：接受概率 exp(−ΔE/T)", "view": "prob-table", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "probability", "note": "同一ΔE=4、同一u=0.5：T=1拒绝，T=10接受", "say": "对变差的候选，接受概率是exp(−ΔE除以T)。注意这是概率，不是\"成功概率\"：掷的是u这个随机数，u小于p才接受。同一个ΔE、同一个u，温度越高p越大——更容易接受后退。", "start": 71.094, "delivery": "voice", "end": 79.392}, {"key": "temp-predict", "chapter": 3, "title": "预测：升温会怎样？", "view": "prob-table", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "predict", "note": "同一ΔE、同一u，只改温度", "question": {"prompt": "ΔE=4，u=0.5。T=1 时 p=exp(−4)≈0.018；T=10 时 p=exp(−0.4)≈0.67。两次判定结果？", "choices": ["T=1 拒绝（0.018<0.5），T=10 接受（0.67>0.5）", "两次都接受", "两次都拒绝"], "answer": 0, "replies": ["u<p 才接受：0.018<0.5 拒绝，0.67>0.5 接受。", "低温下同样的变差几乎总是被拒。", "判定的全部输入是ΔE、T和u，三个都相同才会得到相同结果。"]}, "start": 79.392, "delivery": "voice", "end": 86.828}, {"key": "real-accept", "chapter": 4, "title": "真实轨迹：第6步被接受的变差", "view": "trace-view", "step": 6, "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "accept", "note": "ΔE=10，u=0.144，p=0.379：u<p → 接受；当前变，最好不动", "say": "看真实轨迹的第6步：候选比当前差10，温度12，p等于0.379，抽到的u是0.144，小于p，接受。当前解换成候选，能量上去了；历史最好合法解是另一份保存，不会被覆盖。", "start": 86.828, "delivery": "voice", "end": 95.51}, {"key": "real-reject", "chapter": 4, "title": "真实轨迹：第2步被拒绝", "view": "trace-view", "step": 2, "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "reject", "note": "ΔE=96，u=0.240，p≈0.0003：u>p → 拒绝；当前保持原样", "say": "再看第2步：候选差了96，即使温度12，p也只有0.0003；u是0.240，大于p，拒绝。当前布局和能量都保持原样。拒绝的候选就此丢弃——如果它\"偷偷\"改了当前解，那就是状态机bug，习题里会让你修。", "start": 95.51, "delivery": "voice", "end": 103.88}, {"key": "log-fields", "chapter": 5, "title": "日志七列，一步不缺", "view": "log-table", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 14, "note": "步、T、候选能量、ΔE、u、接受、当前、最好合法", "say": "可复现的搜索要有完整日志：每步记录温度、候选能量、ΔE、抽到的u、是否接受、之后的当前能量和最好合法面积。有了它，任何人用同一种子重放，都能逐步核对。缺一列，复现就有缺口。", "start": 103.88, "delivery": "reading", "end": 119.21}, {"key": "best-monotonic", "chapter": 5, "title": "最好合法解：只减不增", "view": "monotonic-chart", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 14, "note": "seed=3：最好25，最终当前27——两者要分开报告", "say": "历史最好合法面积只会持平或下降。但当前解接受变差后可能变差：seed=3这次运行，最后当前能量27，而最好只有25。报告算法结果时用\"历史最好\"；\"最后一步\"是另一个数。", "start": 119.21, "delivery": "reading", "end": 134.38}, {"key": "budget-design", "chapter": 6, "title": "预算四件套：T0、冷却、步数、停止", "view": "budget-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 13, "note": "初始温度、冷却率、总步数、明确停止条件", "say": "一次完整运行要写清四件事：初始温度、冷却率（本课每步乘0.97）、总步数预算、停止条件。预算花完就停，没有\"跑到位了\"这种模糊说法。写代码时它们都是参数，不是常量。", "start": 134.38, "delivery": "reading", "end": 149.05}, {"key": "equal-budget", "chapter": 6, "title": "等预算比较：T=12 对 T=2", "view": "compare-table07", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 16, "note": "种子{3,7,11}×120步：T12={25,25,25}；T2={28,25,27}", "say": "比较必须等预算、多种子。同一组种子{3,7,11}各跑120步：T=12三次的最好合法面积是25、25、25；T=2是28、25、27。这组数据上T=12更稳，但结论只属于这个五块算例和这些参数——单次运行、单一参数，都撑不起结论。", "start": 149.05, "delivery": "reading", "end": 169.38}, {"key": "penalty", "chapter": 7, "title": "罚项：把越界变成昂贵的错误", "view": "penalty-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 14, "note": "E=盒面积+100×(超宽+超高)；罚项太小→越界解占优", "say": "本课能量是盒面积加100倍的超宽超高——没有线长、时序、拥塞，只评几何。罚项的作用是让越界\"得不偿失\"：罚100时越界候选能量236，输给合法的40；罚改成1，它变成38反而胜出。100不是通用最佳值，是本课模型的选择。", "start": 169.38, "delivery": "reading", "end": 188.71}, {"key": "reachability", "chapter": 7, "title": "温度治不了邻域不可达", "view": "reach-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "seconds": 15, "note": "低温影响接受行为；邻域够不着的目标，调温无济于事", "say": "还有一个容易混的问题：接受行为与可达性。低温让变差难以被接受，搜索走得慢；但如果邻域本身够不着某个区域，调温没用。教材里有个对照：把邻域限制成\"只交换固定原点上已有的模块\"，某些起点就永远到不了最优——本站的邻域是任意交换序列对元素，没有那种锁死。判断慢的原因前，先分清这两类。", "start": 188.71, "delivery": "reading", "end": 212.88}, {"key": "reproducibility", "chapter": 8, "title": "固定种子：复现而非最优", "view": "repro-cards", "rows": [["A", 0, 0, 3, 2], ["B", 3, 0, 2, 3], ["C", 5, 0, 2, 2], ["D", 0, 2, 3, 1], ["E", 7, 0, 2, 2]], "voice": "best", "note": "同种子重放逐步一致；一次成功不代表每次最优", "say": "固定种子让整条轨迹可以逐步重放——这是复现，不是最优性保证。seed=7这次拿到25，换seed=3在T=2下只有28。一次漂亮运行不能证明算法优越，更不能证明全局最优；证据来自等预算、多种子的统计。", "start": 212.88, "delivery": "voice", "end": 221.25}, {"key": "transfer", "chapter": 8, "title": "轮到你：读日志、修bug、跑比较", "view": "board", "rows": [["A", 0, 1, 3, 2], ["B", 3, 0, 2, 3], ["C", 0, 3, 2, 2], ["D", 0, 0, 3, 1], ["E", 2, 3, 2, 2]], "seconds": 11, "note": "三项实验在下方Lab区；比较按钮一次性算完", "say": "下面的实验给你同一条轨迹、一个有bug的状态机和等预算比较按钮。每项都要提交数值和解释——判定的依据是日志，不是感觉。", "start": 221.25, "delivery": "reading", "end": 232.25}], "chapters": ["搜索变量是什么", "三份状态与邻居", "接受判定", "一条真实轨迹", "日志复盘", "预算与等预算比较", "罚项与可达性", "轮到你审计"], "duration": 232.25, "readingSeconds": 171.0, "captions": [{"start": 0, "end": 2.6470588235294117, "text": "前几课解决了\"从编码到布局\"。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 2.6470588235294117, "end": 9.0, "text": "但一个五块问题就有14400个序列对编码，真实芯片的编码空间是天文数字。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 9.0, "end": 11.647058823529411, "text": "逐个试完不现实，需要搜索策略。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 11.647058823529411, "end": 18.0, "text": "本课用可复现的模拟退火：每步只看一个邻居，用明确的规则决定接受还是拒绝。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 18, "end": 36.0, "text": "本课的任务有三层：读懂一条真实轨迹里每一步的决策；审计\"拒绝后当前解被修改\"这类状态机错误；最后用相同种子集合、相同预算做等预算比较，区分邻域不足、接受行为和预算不足。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 36, "end": 42.964285714285715, "text": "先看终点：固定种子7、温度12、120步，这次运行得到的最好合法布局面积25。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 42.964285714285715, "end": 51.0, "text": "注意现在是\"这一次运行\"的结果——它能不能稳定复现、换个种子还好不好，是本课要回答的问题。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 51.0, "end": 57.714, "text": "表示法生成布局，模拟退火则在不同编码之间搜索。", "delivery": "voice", "sourceKey": "start", "words": [{"text": "表示", "start": 51.102083, "end": 51.427624}, {"text": "法生", "start": 51.440625, "end": 51.805208}, {"text": "成", "start": 51.805208, "end": 51.987499}, {"text": "布局", "start": 52.000541, "end": 52.586499}, {"text": "模拟", "start": 52.951041000000004, "end": 53.276582}, {"text": "退火", "start": 53.289583, "end": 53.914583}, {"text": "则", "start": 54.044791000000004, "end": 54.214082}, {"text": "在", "start": 54.214083, "end": 54.331291}, {"text": "不同", "start": 54.357291000000004, "end": 54.695832}, {"text": "编码", "start": 54.708875, "end": 55.021375}, {"text": "之间", "start": 55.034375, "end": 55.294791000000004}, {"text": "搜索", "start": 55.307833, "end": 55.750541}]}, {"start": 57.714, "end": 64.836, "text": "这里每次交换某一个排列里的两个名称，再重新解码并计算能量。", "delivery": "voice", "sourceKey": "neighbor", "words": [{"text": "这里", "start": 57.816083000000006, "end": 58.115583}, {"text": "每次", "start": 58.141625000000005, "end": 58.51925}, {"text": "交换", "start": 58.532250000000005, "end": 58.883832999999996}, {"text": "某", "start": 58.909833000000006, "end": 59.040041}, {"text": "一个", "start": 59.053083, "end": 59.23537400000001}, {"text": "排列", "start": 59.248374999999996, "end": 59.560874999999996}, {"text": "里", "start": 59.560874999999996, "end": 59.638999999999996}, {"text": "的", "start": 59.638999999999996, "end": 59.743166}, {"text": "两", "start": 59.769208000000006, "end": 59.925458000000006}, {"text": "个", "start": 59.925458000000006, "end": 60.003583000000006}, {"text": "名称", "start": 60.016625000000005, "end": 60.563500000000005}, {"text": "再", "start": 60.928083, "end": 61.097374}, {"text": "重新", "start": 61.110375000000005, "end": 61.488}, {"text": "解码", "start": 61.501000000000005, "end": 61.943708}, {"text": "并", "start": 62.047875000000005, "end": 62.204125000000005}, {"text": "计算", "start": 62.217124999999996, "end": 62.477541}, {"text": "能量", "start": 62.490583, "end": 62.868207999999996}]}, {"start": 64.836, "end": 71.094, "text": "能量下降就接受，能量上升则不必立即拒绝。", "delivery": "voice", "sourceKey": "delta", "words": [{"text": "能量", "start": 64.938083, "end": 65.289666}, {"text": "下降", "start": 65.302666, "end": 65.693291}, {"text": "就", "start": 65.719333, "end": 65.797458}, {"text": "接受", "start": 65.8105, "end": 66.292291}, {"text": "能量", "start": 66.669875, "end": 67.021458}, {"text": "上升", "start": 67.034458, "end": 67.594374}, {"text": "则", "start": 67.711541, "end": 67.880832}, {"text": "不必", "start": 67.893833, "end": 68.32354099999999}, {"text": "立即", "start": 68.349541, "end": 68.649041}, {"text": "拒绝", "start": 68.662041, "end": 69.130791}]}, {"start": 71.094, "end": 79.392, "text": "对于变差的候选，接受概率是负的能量差除以温度，再取指数。", "delivery": "voice", "sourceKey": "probability", "words": [{"text": "对于", "start": 71.19608299999999, "end": 71.57370799999998}, {"text": "变差", "start": 71.59975, "end": 71.951291}, {"text": "的", "start": 71.951291, "end": 72.029416}, {"text": "候选", "start": 72.04245799999998, "end": 72.602374}, {"text": "接受", "start": 72.927875, "end": 73.26641599999999}, {"text": "概率", "start": 73.279416, "end": 73.85233199999999}, {"text": "是", "start": 73.96954099999999, "end": 74.22995699999998}, {"text": "负", "start": 74.22995799999998, "end": 74.39920799999999}, {"text": "的", "start": 74.39920799999999, "end": 74.568499}, {"text": "能量", "start": 74.59454099999999, "end": 74.94608199999999}, {"text": "差除", "start": 74.94608299999999, "end": 75.623166}, {"text": "以", "start": 75.72733299999999, "end": 75.88358299999999}, {"text": "温度", "start": 75.896625, "end": 76.31329099999999}, {"text": "再", "start": 76.521625, "end": 76.795041}, {"text": "取", "start": 76.795041, "end": 76.990374}, {"text": "指数", "start": 77.003375, "end": 77.420041}]}, {"start": 79.392, "end": 86.828, "text": "同样一次变差，如果温度更高，它会更容易被接受吗？", "delivery": "voice", "sourceKey": "predict", "words": [{"text": "同样", "start": 79.494083, "end": 79.845666}, {"text": "一次", "start": 79.858666, "end": 80.066999}, {"text": "变差", "start": 80.080041, "end": 80.639957}, {"text": "如果", "start": 81.108666, "end": 81.356082}, {"text": "温度", "start": 81.382125, "end": 81.642541}, {"text": "更", "start": 81.655541, "end": 81.850874}, {"text": "高", "start": 81.850875, "end": 82.163375}, {"text": "它", "start": 82.475875, "end": 82.632125}, {"text": "会", "start": 82.632125, "end": 82.762333}, {"text": "更", "start": 82.788375, "end": 82.918583}, {"text": "容易", "start": 82.918583, "end": 83.400374}, {"text": "被", "start": 83.50450000000001, "end": 83.64775}, {"text": "接受", "start": 83.66075000000001, "end": 84.012333}, {"text": "吗", "start": 84.012333, "end": 84.220666}]}, {"start": 86.828, "end": 95.50999999999999, "text": "看这次实际接受的变差候选；当前解改变，但历史最好合法解不会被覆盖。", "delivery": "voice", "sourceKey": "accept", "words": [{"text": "看", "start": 86.930083, "end": 87.151458}, {"text": "这次", "start": 87.164458, "end": 87.476958}, {"text": "实际", "start": 87.503, "end": 87.88062500000001}, {"text": "接受", "start": 87.893625, "end": 88.206125}, {"text": "的", "start": 88.206125, "end": 88.34937500000001}, {"text": "变差", "start": 88.375416, "end": 88.753041}, {"text": "候选", "start": 88.766041, "end": 89.260832}, {"text": "当前", "start": 89.625416, "end": 90.029041}, {"text": "解", "start": 90.029041, "end": 90.159249}, {"text": "改变", "start": 90.172291, "end": 90.641041}, {"text": "但", "start": 90.953541, "end": 91.148874}, {"text": "历史", "start": 91.16187500000001, "end": 91.47437500000001}, {"text": "最好", "start": 91.500416, "end": 91.838957}, {"text": "合法", "start": 91.851958, "end": 92.242583}, {"text": "解", "start": 92.242583, "end": 92.555083}, {"text": "不会", "start": 92.672291, "end": 92.97174900000002}, {"text": "被", "start": 92.97175000000001, "end": 93.075916}, {"text": "覆盖", "start": 93.08895800000002, "end": 93.531666}]}, {"start": 95.50999999999999, "end": 103.88, "text": "另一份候选被拒绝，当前布局保持原样；随机数和概率共同决定这一步。", "delivery": "voice", "sourceKey": "reject", "words": [{"text": "另", "start": 95.61208299999998, "end": 95.820416}, {"text": "一", "start": 95.820416, "end": 95.91158200000001}, {"text": "份", "start": 95.91158300000001, "end": 96.054833}, {"text": "候选", "start": 96.06783300000001, "end": 96.49754100000001}, {"text": "被", "start": 96.523541, "end": 96.66679099999999}, {"text": "拒绝", "start": 96.679791, "end": 97.226666}, {"text": "当前", "start": 97.56520799999998, "end": 97.94283300000001}, {"text": "布局", "start": 97.95583299999998, "end": 98.372499}, {"text": "保持", "start": 98.398541, "end": 98.671999}, {"text": "原样", "start": 98.685, "end": 99.101666}, {"text": "随机数", "start": 99.45325, "end": 100.10429099999999}, {"text": "和", "start": 100.13033300000001, "end": 100.221499}, {"text": "概率", "start": 100.2345, "end": 100.664208}, {"text": "共同", "start": 100.781375, "end": 101.22408300000001}, {"text": "决定", "start": 101.23708299999998, "end": 101.484499}, {"text": "这", "start": 101.51054099999999, "end": 101.601666}, {"text": "一", "start": 101.601666, "end": 101.718874}, {"text": "步", "start": 101.718875, "end": 101.94024999999999}]}, {"start": 103.88, "end": 113.32755813953489, "text": "可复现的搜索要有完整日志：每步记录温度、候选能量、ΔE、抽到的u、是否接受、之后的当前能量和最好合法面积。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 113.32755813953489, "end": 117.24918604651162, "text": "有了它，任何人用同一种子重放，都能逐步核对。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 117.24918604651162, "end": 119.21, "text": "缺一列，复现就有缺口。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 119.21, "end": 122.0655294117647, "text": "历史最好合法面积只会持平或下降。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 122.0655294117647, "end": 129.56129411764707, "text": "但当前解接受变差后可能变差：seed=3这次运行，最后当前能量27，而最好只有25。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 129.56129411764707, "end": 134.38, "text": "报告算法结果时用\"历史最好\"；\"最后一步\"是另一个数。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 134.38, "end": 142.25170731707317, "text": "一次完整运行要写清四件事：初始温度、冷却率（本课每步乘0.97）、总步数预算、停止条件。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 142.25170731707317, "end": 146.18756097560976, "text": "预算花完就停，没有\"跑到位了\"这种模糊说法。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 146.18756097560976, "end": 149.05, "text": "写代码时它们都是参数，不是常量。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 149.04999999999998, "end": 151.15310344827586, "text": "比较必须等预算、多种子。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 151.15310344827586, "end": 160.96758620689656, "text": "同一组种子{3,7,11}各跑120步：T=12三次的最好合法面积是25、25、25；T=2是28、25、27。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 160.96758620689656, "end": 169.38, "text": "这组数据上T=12更稳，但结论只属于这个五块算例和这些参数——单次运行、单一参数，都撑不起结论。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 169.38, "end": 175.70618181818182, "text": "本课能量是盒面积加100倍的超宽超高——没有线长、时序、拥塞，只评几何。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 175.70618181818182, "end": 185.19545454545454, "text": "罚项的作用是让越界\"得不偿失\"：罚100时越界候选能量236，输给合法的40；罚改成1，它变成38反而胜出。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 185.19545454545454, "end": 188.70999999999998, "text": "100不是通用最佳值，是本课模型的选择。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 188.70999999999998, "end": 192.1876978417266, "text": "还有一个容易混的问题：接受行为与可达性。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 192.1876978417266, "end": 198.62143884892083, "text": "低温让变差难以被接受，搜索走得慢；但如果邻域本身够不着某个区域，调温没用。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 198.62143884892083, "end": 210.271726618705, "text": "教材里有个对照：把邻域限制成\"只交换固定原点上已有的模块\"，某些起点就永远到不了最优——本站的邻域是任意交换序列对元素，没有那种锁死。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 210.271726618705, "end": 212.87999999999997, "text": "判断慢的原因前，先分清这两类。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 212.88, "end": 221.25, "text": "最后查看这次固定种子的最好合法解；一次成功不代表每次都能得到最优。", "delivery": "voice", "sourceKey": "best", "words": [{"text": "最后", "start": 212.982083, "end": 213.281583}, {"text": "查看", "start": 213.294583, "end": 213.919583}, {"text": "这次", "start": 214.036791, "end": 214.427416}, {"text": "固定", "start": 214.453458, "end": 214.765958}, {"text": "种子", "start": 214.778958, "end": 215.039374}, {"text": "的", "start": 215.039375, "end": 215.130541}, {"text": "最好", "start": 215.156583, "end": 215.482124}, {"text": "合", "start": 215.49512500000003, "end": 215.599291}, {"text": "法解", "start": 215.599291, "end": 216.12012400000003}, {"text": "一次", "start": 216.445625, "end": 216.70604100000003}, {"text": "成功", "start": 216.719083, "end": 217.278999}, {"text": "不", "start": 217.396166, "end": 217.552416}, {"text": "代表", "start": 217.552416, "end": 217.825874}, {"text": "每次", "start": 217.851875, "end": 218.34666600000003}, {"text": "都", "start": 218.359708, "end": 218.50291600000003}, {"text": "能", "start": 218.50291600000003, "end": 218.607082}, {"text": "得到", "start": 218.62012500000003, "end": 218.85450000000003}, {"text": "最", "start": 218.8675, "end": 219.036791}, {"text": "优", "start": 219.036791, "end": 219.29720700000001}]}, {"start": 221.25, "end": 227.21610169491527, "text": "下面的实验给你同一条轨迹、一个有bug的状态机和等预算比较按钮。", "delivery": "reading", "sourceKey": null, "words": []}, {"start": 227.21610169491527, "end": 232.25, "text": "每项都要提交数值和解释——判定的依据是日志，不是感觉。", "delivery": "reading", "sourceKey": null, "words": []}], "cuts": [{"scene": "components", "sourceKey": "start", "sourceStart": 0.0, "sourceEnd": 6.714, "start": 51.0, "end": 57.714}, {"scene": "neighbor-swap", "sourceKey": "neighbor", "sourceStart": 6.714, "sourceEnd": 13.836, "start": 57.714, "end": 64.836}, {"scene": "delta", "sourceKey": "delta", "sourceStart": 13.836, "sourceEnd": 20.094, "start": 64.836, "end": 71.094}, {"scene": "probability", "sourceKey": "probability", "sourceStart": 20.094, "sourceEnd": 28.392, "start": 71.094, "end": 79.392}, {"scene": "temp-predict", "sourceKey": "predict", "sourceStart": 28.392, "sourceEnd": 35.828, "start": 79.392, "end": 86.828}, {"scene": "real-accept", "sourceKey": "accept", "sourceStart": 35.828, "sourceEnd": 44.51, "start": 86.828, "end": 95.50999999999999}, {"scene": "real-reject", "sourceKey": "reject", "sourceStart": 44.51, "sourceEnd": 52.88, "start": 95.50999999999999, "end": 103.88}, {"scene": "reproducibility", "sourceKey": "best", "sourceStart": 52.88, "sourceEnd": 61.25, "start": 212.88, "end": 221.25}], "newSpeech": false, "audioSha256": "6fb9c22d5a63b428c6670579cd7571edd7369ac2bd584c9dade609bf0fc61717", "sourceHashes": {"content/interactive07.mjs": "9f1cb5833ec395bea836ca7de9ab6f61f2f1291d7177d935e9a677d7f3ba9b6a", "dist/media/07/zh.m4a": "ed4f74c6f09552c646764a22648446b1513b34a175d67ad5c522f4b7f5b1503b", "dist/media/07/zh.json": "50eb8d056ba294600f18b849c6d065beeda890642a7333974e4854ba65fcb2b0", "dist/assets/anneal07.mjs": "2bff82789b1919b8e8a1cb34f351b8f7d66eb678167b3686d17890f795962ec8"}};
